"245 :   static boolean isSubtype(ObjectType typeA, RecordType typeB) {
246 :     // typeA is a subtype of record type typeB iff:
247 :     // 1) typeA has all the properties declared in typeB.
248 :     // 2) And for each property of typeB,
249 :     //    2a) if the property of typeA is declared, it must be equal
250 :     //        to the type of the property of typeB,
251 :     //    2b) otherwise, it must be a subtype of the property of typeB.
252 :     //
253 :     // To figure out why this is true, consider the following pseudo-code:
254 :     // /** @type {{a: (Object,null)}} */ var x;
255 :     // /** @type {{a: !Object}} */ var y;
256 :     // var z = {a: {}};
257 :     // x.a = null;
258 :     //
259 :     // y cannot be assigned to x, because line 4 would violate y's declared
260 :     // properties. But z can be assigned to x. Even though z and y are the
261 :     // same type, the properties of z are inferred--and so an assignment
262 :     // to the property of z would not violate any restrictions on it.
263 :     for (String property : typeB.properties.keySet()) {
264 :       if (!typeA.hasProperty(property)) {
265 :         return false;
266 :       }
267 : 
268 :       JSType propA = typeA.getPropertyType(property);
269 :       JSType propB = typeB.getPropertyType(property);
270 :       if (!propA.isUnknownType() && !propB.isUnknownType()) {
271 :         if (typeA.isPropertyTypeDeclared(property)) {
272 :           if (!propA.isEquivalentTo(propB)) {
273 :             return false;
274 :           }
275 :         } else {
276 :           if (!propA.isSubtype(propB)) {
277 :             return false;
278 :           }
279 :         }
280 :       }
281 :     }
282 : 
283 :     return true;
